const fs = require("node:fs");
const path = require("node:path");
const { execFileSync } = require("node:child_process");

function sourceOutputs(root) {
  const outputs = [];
  const sourceRoot = path.join(root, "src");
  const visit = (directory, relative) => {
    for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
      const name = path.join(relative, entry.name);
      const absolute = path.join(root, name);
      if (entry.isDirectory()) {
        if (name !== path.join("src", "dist")) visit(absolute, name);
        continue;
      }
      if (!entry.isFile()) continue;
      if (
        /\.(?:ts|mts|cts|tsx)$/.test(entry.name) &&
        !entry.name.endsWith(".d.ts")
      ) {
        const extension = path.extname(entry.name);
        const stem = name.slice(0, -extension.length);
        const javascript = {
          ".ts": ".js",
          ".mts": ".mjs",
          ".cts": ".cjs",
          ".tsx": ".jsx",
        }[extension];
        const declaration = {
          ".ts": ".d.ts",
          ".mts": ".d.mts",
          ".cts": ".d.cts",
          ".tsx": ".d.ts",
        }[extension];
        for (const output of [stem + javascript, stem + declaration])
          if (fs.existsSync(path.join(root, output))) outputs.push(output);
      } else if (/\.(?:js|cjs|mjs)$/.test(entry.name)) {
        const contents = fs.readFileSync(absolute, "utf8");
        if (contents.includes("Generated by stage-compatibility;"))
          outputs.push(name);
      }
    }
  };
  visit(sourceRoot, "src");
  return outputs;
}

// Include workspace declarations/build info, transitional runtime modules and
// fixtures as well as the installed dist runtime. Consumers must not recompile.
function buildOutputs(root) {
  const definitionsPointer = path.join(
    root,
    "dist/runtime/python/typing/current.json",
  );
  if (
    !fs.existsSync(definitionsPointer) ||
    !fs.lstatSync(definitionsPointer).isFile()
  )
    throw new Error(
      "Missing generated Python definitions pointer: dist/runtime/python/typing/current.json",
    );
  const outputs = [
    "dist",
    "src/dist",
    "server.mjs",
    "docs/COMMAND_REFERENCE.md",
    "docs/COMMAND_COVERAGE.md",
    ...sourceOutputs(root),
    ...fs
      .readdirSync(path.join(root, "packages"))
      .map((name) => `packages/${name}/dist`),
    ...[
      "closed-scratch-artifacts",
      "closed-epoch-successor",
      "historical-module",
    ].map((name) => `tests/fixtures/${name}.cjs`),
  ];
  for (const output of outputs) fs.lstatSync(path.join(root, output));
  return outputs;
}

function pack(root, archive) {
  // tar, unlike raw upload-artifact, retains executable bits and symlinks.
  execFileSync("tar", ["-czf", archive, "--", ...buildOutputs(root)], {
    cwd: root,
  });
}

module.exports = { buildOutputs, pack };
if (require.main === module) {
  if (process.argv.length !== 3)
    throw new Error("Usage: ci-build-artifact.cjs ARCHIVE");
  pack(path.resolve(__dirname, "../.."), path.resolve(process.argv[2]));
}
